static void print_spec_symbol(str)
    token str;
{
    if (!strcmp(str,"("))
        fprintf(stdout, "lparen.");
    else if (!strcmp(str,")"))
        fprintf(stdout, "rparen.");
    else if (!strcmp(str,"["))
        fprintf(stdout, "lsquare.");
    else if (!strcmp(str,"]"))
        fprintf(stdout, "rsquare.");
    else if (!strcmp(str,"'"))
        fprintf(stdout, "quote.");
    else if (!strcmp(str,"`"))
        fprintf(stdout, "bquote.");
    else if (!strcmp(str,","))
        fprintf(stdout, "comma.");
    else
        fprintf(stdout, "unknown_spec_symbol.");

